package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtils_toBoolean_TriageGen1Test {

    @Test
    public void testToBoolean_Null() {
        assertFalse(BooleanUtils.toBoolean(null));
    }

    @Test
    public void testToBoolean_TrueInterned() {
        // Testing the (str == "true") branch
        assertTrue(BooleanUtils.toBoolean("true"));
    }

    @Test
    public void testToBoolean_TrueNonInterned() {
        // Testing the case 4 branch for 'true'
        assertTrue(BooleanUtils.toBoolean(new String("true")));
    }

    @Test
    public void testToBoolean_TrueCaseInsensitive() {
        assertTrue(BooleanUtils.toBoolean("TRUE"));
        assertTrue(BooleanUtils.toBoolean("TrUe"));
        assertTrue(BooleanUtils.toBoolean("tRuE"));
        assertTrue(BooleanUtils.toBoolean("T"); // length 1, should be false
    }

    @Test
    public void testToBoolean_Case4_TrueVariations() {
        assertTrue(BooleanUtils.toBoolean("tRuE"));
        assertTrue(BooleanUtils.toBoolean("T r u e".replace(" ", ""))); // length 4 logic
        assertTrue(BooleanUtils.toBoolean("TRUe"));
        assertTrue(BooleanUtils.toBoolean("trUE"));
        assertTrue(BooleanUtils.toBoolean("TrUe"));

        // Negative cases for length 4 starting with 't'
        assertFalse(BooleanUtils.toBoolean("tfoo"));
        assertFalse(BooleanUtils.toBoolean("trux"));
        assertFalse(BooleanUtils.toBoolean("trxe"));
        assertFalse(BooleanUtils.toBoolean("txue"));

        // Negative cases for length 4 starting with 'T'
        assertFalse(BooleanUtils.toBoolean("Tfoo"));
        assertFalse(BooleanUtils.toBoolean("TRUx"));
        assertFalse(BooleanUtils.toBoolean("Trxe"));
    }

    @Test
    public void testToBoolean_Case3_YesVariations() {
        // Case 'y'
        assertTrue(BooleanUtils.toBoolean("yes"));
        assertTrue(BooleanUtils.toBoolean("yeS"));
        assertTrue(BooleanUtils.toBoolean("yEs"));
        assertTrue(BooleanUtils.toBoolean("YEs"));

        // Case 'Y'
        assertTrue(BooleanUtils.toBoolean("YES"));
        assertTrue(BooleanUtils.toBoolean("YeS"));
        assertTrue(BooleanUtils.toBoolean("yEs")); // Handled by 'y' branch

        // Negative cases for length 3
        assertFalse(BooleanUtils.toBoolean("yea"));
        assertFalse(BooleanUtils.toBoolean("yos"));
        assertFalse(BooleanUtils.toBoolean("yss"));
        assertFalse(BooleanUtils.toBoolean("abc"));
        assertFalse(BooleanUtils.toBoolean("Yee"));
        assertFalse(BooleanUtils.toBoolean("YEs")); // Redundant but covers logic
    }

    @Test
    public void testToBoolean_Case2_OnVariations() {
        assertTrue(BooleanUtils.toBoolean("on"));
        assertTrue(BooleanUtils.toBoolean("ON"));
        assertTrue(BooleanUtils.toBoolean("oN"));
        assertTrue(BooleanUtils.toBoolean("On"));

        // Negative cases for length 2
        assertFalse(BooleanUtils.toBoolean("of"));
        assertFalse(BooleanUtils.toBoolean("no"));
        assertFalse(BooleanUtils.toBoolean("oo"));
        assertFalse(BooleanUtils.toBoolean("nn"));
    }

    @Test
    public void testToBoolean_OtherLengths() {
        assertFalse(BooleanUtils.toBoolean("t"));
        assertFalse(BooleanUtils.toBoolean("truee"));
        assertFalse(BooleanUtils.toBoolean("yesyes"));
        assertFalse(BooleanUtils.toBoolean(""));
    }

    @Test
    public void testToBoolean_FalseStrings() {
        assertFalse(BooleanUtils.toBoolean("false"));
        assertFalse(BooleanUtils.toBoolean("no")); // length 2 check
        assertFalse(BooleanUtils.toBoolean("off")); // length 3 check
    }
}
